// Parse only supported text messages. Webhook is acknowledged immediately.
// Fail closed unless the configured sender ID is the Meta TEST phone-number ID.
const mode = $env.WHATSAPP_MODE || 'test';
const approved = ($env.WHATSAPP_PRODUCTION_APPROVED || 'false').toLowerCase() === 'true';
const senderId = $env.WHATSAPP_PHONE_NUMBER_ID || '';
const testId = $env.WHATSAPP_TEST_PHONE_NUMBER_ID || '';
if (mode !== 'test' || !testId || senderId !== testId) return [];
const body = $json.body ?? $json;
if (body.object !== 'whatsapp_business_account') return [];
const out = [];
for (const entry of body.entry ?? []) for (const change of entry.changes ?? []) {
  const value = change.value ?? {};
  for (const m of value.messages ?? []) {
    if (m.type !== 'text' || !m.text?.body || !m.id || !m.from) continue;
    const text = String(m.text.body).trim().slice(0, 2000);
    const low = text.toLowerCase();
    const optOut = /^(stop|unsubscribe|cancel|opt\\s*out|band\\s*karo|message\\s*mat\\s*karo|mat\\s*bhejo|बंद\\s*करो|मैसेज\\s*मत\\s*करो)$/i.test(low);
    const human = /(talk to human|human agent|real person|staff se baat|insaan se baat|sales executive|representative)/i.test(low);
    let intent = 'ENQUIRY';
    if (optOut) intent = 'OPT_OUT';
    else if (human) intent = 'HUMAN_REQUEST';
    else if (/(test.?ride|test drive|टेस्ट राइड)/i.test(low)) intent = 'TEST_RIDE';
    else if (/(callback|call back|call me|फोन|कॉल)/i.test(low)) intent = 'CALLBACK';
    else if (/(emi|finance|loan|down payment|डाउन पेमेंट)/i.test(low)) intent = 'FINANCE';
    else if (/(price|on.?road|kitne|कीमत|दाम)/i.test(low)) intent = 'PRICE';
    out.push({json:{messageId:m.id,waId:m.from,text,intent,displayName:value.contacts?.[0]?.profile?.name || ''}});
  }
}
return out;

const p = $('Conversation Policy Router').item.json;
const facts = {
  dealershipName: $env.DEALERSHIP_NAME || 'The Bike Yard',
  location: $env.DEALERSHIP_LOCATION || 'Thane, Maharashtra (MH-04)',
  address: $env.DEALERSHIP_ADDRESS || null,
  hours: $env.DEALERSHIP_HOURS || null,
  phone: $env.DEALERSHIP_PHONE || null,
  brandsNote: $env.DEALERSHIP_BRANDS_NOTE || null
};
const system = 'You are an automated virtual assistant for ' + facts.dealershipName + '. Match the customer language (Hinglish, Hindi, English). Keep replies short and warm. VERIFIED KNOWLEDGE ONLY: ' + JSON.stringify(facts) + '. Never invent stock, price, on-road quote, discounts, specifications, delivery, finance approval or availability. If unknown, say staff must confirm and offer callback. Test rides/callbacks are requests, never confirmed. EMI is only an estimate with explicit rate, tenure and down-payment assumptions; if assumptions are missing, do not calculate. Escalate complaints, negotiation, finance eligibility, payment issues, uncertain facts and human requests. Never impersonate a human. Return only reply text.';
return [{json:{waId:p.waId,intent:p.intent,messageId:p.messageId,system,userText:p.text}}];
